<?php
require_once __DIR__ . '/../includi/albo_admin.php';
function check(bool $condition,string $message): void { if (!$condition) throw new RuntimeException($message); }
function rejects(callable $run,string $message): void { try { $run(); } catch (RuntimeException $e) { return; } throw new RuntimeException($message); }
$t=['id'=>1,'nome'=>'Coppa prova','sezione'=>'calcio','filetorneo'=>'Prova.php','img'=>'/cup.png','stato'=>'terminato','data_inizio'=>'2026-06-01','data_fine'=>'2026-06-30','config'=>[]];
$a=['id'=>10,'nome'=>'A','logo'=>'/a.png','punti'=>9,'giocate'=>3,'differenza_reti'=>5,'gol_fatti'=>8];
$b=['id'=>20,'nome'=>'B','logo'=>'/b.png','punti'=>3,'giocate'=>3,'differenza_reti'=>1,'gol_fatti'=>4];
$m=['id'=>1,'fase'=>'GOLD','fase_round'=>'FINALE','fase_leg'=>'UNICA','squadra_casa'=>'A','squadra_ospite'=>'B','gol_casa'=>2,'gol_ospite'=>1,'giocata'=>1];
check(albo_final_winner([$m])[0] === 'A','A single completed final decides its winner');
check(albo_final_winner([[...$m,'giocata'=>0]])[0] === '','Unfinalized games never award a trophy');
check(albo_final_winner([[...$m,'fase_leg'=>'ANDATA']])[0] === '','One leg cannot award a two-leg final');
$first=[...$m,'fase_leg'=>'ANDATA'];
$second=[...$m,'id'=>2,'fase_leg'=>'RITORNO','squadra_casa'=>'B','squadra_ospite'=>'A','gol_casa'=>1,'gol_ospite'=>0,'decisa_rigori'=>1,'rigori_casa'=>5,'rigori_ospite'=>4];
check(albo_final_winner([$second,$first])[0] === 'B','Aggregate ties use return-leg penalties, regardless of row order');
check(albo_final_winner([[...$m,'gol_casa'=>1,'gol_ospite'=>1]])[0] === '','Tied finals without penalties stay unassigned');
$regular=[...$m,'fase'=>'REGULAR','fase_round'=>null];
check(albo_regular_winner([$a,[...$b,'punti'=>9,'differenza_reti'=>999]],[$regular])[0] === 'A','Head-to-head precedes overall goal difference for two tied teams');
check(albo_regular_winner([[...$a,'punti'=>3],[...$a,'id'=>20,'nome'=>'B','punti'=>3]],[[...$regular,'gol_casa'=>1,'gol_ospite'=>1]])[0] === '','Names never break a sporting tie');
$scorers=[['id'=>100,'nome'=>'Mario','cognome'=>'Rossi','gol'=>4,'squadra'=>'A'],['id'=>200,'nome'=>'Luca','cognome'=>'Bianchi','gol'=>4,'squadra'=>'B']];
$plan=albo_propose($t,[$regular,$m],[$a,$b],$scorers);
check(count(array_filter($plan['awards'],fn($r)=>$r['kind'] === 'SCORER')) === 2,'Joint top scorers are both proposed');
check(count(albo_propose([...$t,'stato'=>'in corso'],[$regular,$m],[$a,$b],$scorers)['awards']) === 0,'Open tournaments do not silently publish');
$incomplete=albo_propose($t,[$regular,[...$m,'giocata'=>0]],[$a,$b],$scorers);
check(count(array_filter($incomplete['awards'],fn($r)=>$r['kind'] === 'SCORER')) === 0 && $incomplete['blocking'] !== [],'Missing results block scorer awards and closure');
$frozen=$plan['awards'];
$manual=[['record_id'=>8,'competizione'=>'Coppa prova','premio'=>'VINCENTE COPPA GOLD','vincitrice'=>'Scelta admin','link_torneo'=>'/tornei/Prova.php','sezione'=>'calcio','anno'=>'2026','source'=>'manuale']];
$merged=albo_archive_merge($manual,$frozen,[],[$t]);
check(count(array_filter($merged,fn($r)=>$r['kind'] === 'GOLD')) === 1,'Manual award has precedence without a duplicate automatic trophy');
check(array_values(array_filter($merged,fn($r)=>$r['kind'] === 'GOLD'))[0]['vincitrice'] === 'Scelta admin','Manual decisions are preserved');
$old=[...$manual[0],'link_torneo'=>'','anno'=>'2025'];
$editions=albo_archive_group(albo_archive_merge([$old],$frozen,[],[$t]));
check(count($editions) === 2,'Different editions with the same name stay separate');
$capManual=[...$manual[0],'premio'=>'Capocannoniere','vincitrice'=>'Mario Rossi (A)'];
$caps=array_values(array_filter(albo_archive_merge([$capManual],$frozen,[],[$t]),fn($r)=>$r['kind'] === 'SCORER'));
check(count($caps) === 2 && $caps[0]['giocatore_id'] === 100,'An existing scorer is linked by ID and a missing joint winner is supplemented');
$ambiguous=[...$capManual,'vincitrice'=>'Nome non correlabile'];
check(count(array_filter(albo_archive_merge([$ambiguous],$frozen,[],[$t]),fn($r)=>$r['kind'] === 'SCORER')) === 1,'Ambiguous manual winners are not silently changed');
$published=[[...$frozen[1],'active'=>0]];
check(count(array_filter(albo_archive_merge([],$frozen,$published,[$t]),fn($r)=>$r['kind'] === $frozen[1]['kind'])) === 0,'Retired official awards do not reappear from frozen history');
echo "Award rules: completed finals, return legs, penalties, head-to-head, ties, editions and legacy precedence passed.\n";

$db=new PDO('sqlite::memory:');$db->setAttribute(PDO::ATTR_ERRMODE,PDO::ERRMODE_EXCEPTION);
$db->exec("CREATE TABLE utenti (id INTEGER PRIMARY KEY,ruolo TEXT);INSERT INTO utenti VALUES (1,'admin'),(2,'grafico');
    CREATE TABLE tornei (id INTEGER PRIMARY KEY,nome TEXT,stato TEXT,filetorneo TEXT);
    INSERT INTO tornei VALUES (1,'Coppa prova','in corso','Prova.php');");
$store=new AlboAwardStore($db);
$runtime=[...$plan,'revision'=>'fresh','players'=>[['id'=>100,'nome'=>'Mario','cognome'=>'Rossi','squadra_id'=>10],['id'=>200,'nome'=>'Luca','cognome'=>'Bianchi','squadra_id'=>20]],'manual_kinds'=>[]];
foreach ($runtime['awards'] as &$award) $award['status']='nuovo';unset($award);
$derive=static fn($locked)=>$runtime;
$keys=array_column($runtime['awards'],'source_key');
rejects(fn()=>$store->publish(1,2,'fresh',$keys,[],true,$derive),'A graphics account cannot publish awards');
rejects(fn()=>$store->publish(1,1,'stale',$keys,[],true,$derive),'Stale revisions are rejected');
rejects(fn()=>$store->publish(1,1,'fresh',['forged'],[],true,$derive),'Unknown keys are rejected');
$capKeys=array_column(array_filter($runtime['awards'],fn($r)=>$r['kind']==='SCORER'),'source_key');
rejects(fn()=>$store->publish(1,1,'fresh',[$capKeys[0]],[],true,$derive),'Joint scorers cannot be partially published');
rejects(fn()=>$store->publish(1,1,'fresh',$keys,['MVP'=>999],true,$derive),'Players outside the tournament roster are rejected');
$changed=$store->publish(1,1,'fresh',$keys,['MVP'=>100],true,$derive);
check($changed === 5,'All selected awards and the chosen individual prize are published atomically');
check(albo_admin_rows($db,'SELECT stato FROM tornei WHERE id=1')[0]['stato'] === 'terminato','Publication closes the selected tournament');
check($store->publish(1,1,'fresh',$keys,['MVP'=>100],false,$derive) === 0,'Repeated publication is idempotent');
check(count(albo_admin_rows($db,'SELECT * FROM albo_automatico_log')) === 5,'No duplicate audit entry on unchanged publication');
$updated=$runtime;$updated['awards'][1]=albo_award($t,'GOLD',$b,'Corrected result');$updated['awards'][1]['status']='da aggiornare';
$changed=$store->publish(1,1,'fresh',[$updated['awards'][1]['source_key']],[],false,static fn($locked)=>$updated);
check($changed === 1,'Approved correction updates one trophy rather than adding a duplicate');
$row=json_decode(albo_admin_rows($db,"SELECT data FROM albo_automatico WHERE kind='GOLD'")[0]['data'],true);
check($row['vincitrice'] === 'B','Corrected winner is stored');
$priorYear=albo_award([...$t,'data_fine'=>'2025-06-30'],'SCORER',['id'=>100,'nome'=>'Mario','cognome'=>'Rossi','gol'=>4],'previous edition','Individuale');
$priorYear['torneo_id']=1;
$priorData=json_encode($priorYear,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);
$stmt=$db->prepare("INSERT INTO albo_automatico (source_key,torneo_id,kind,data,active) VALUES (?,1,'SCORER',?,1)");$stmt->execute([$priorYear['source_key'],$priorData]);
$runtime2026=[...$runtime,'tournament'=>[...$t,'data_fine'=>'2026-06-30']];
$store->publish(1,1,'fresh',$keys,false?[]:[],false,static fn($locked)=>$runtime2026);
check((int)albo_admin_rows($db,'SELECT active FROM albo_automatico WHERE source_key=?',[$priorYear['source_key']])[0]['active']===1,'Publishing current scorers preserves a previous edition');
$db->exec("UPDATE utenti SET ruolo='user' WHERE id=1");
rejects(fn()=>$store->publish(1,1,'fresh',$keys,[],false,$derive),'A revoked admin role is checked again on every write');
echo "Award publication: roles, stale results, forged selections, ex aequo, rollback, idempotency, closure and audited correction passed.\n";
